//generic default keymap with Razor defaults (+ mode toggle)

    /*
     * ┌───┬───┬───┬───┬───┐
     * │Esc│ 1 │ 2 │ 3 │ 4 │
     * ├───┼───┼───┼───┼───┤
     * │Tab│ q │ w │ e │ r │
     * ├───┼───┼───┼───┼───┤
     * │Cap│ a │ s │ d │ f │
     * ├───┼───┼───┼───┼───┤
     * │Shi│ z │ x │ c │ v │
     * ├───┼───┼───┼───┼───┤
     * │Alt│ ↑ │ ↓ │ → │ ← │
     * ├───────┴┬──┴───┴───┤
     * │Spacebar│change map│
     * └────────┴──────────┘
     */

     [0] = LAYOUT(
        KC_ESC, KC_1, KC_2, KC_3, KC_4,
        KC_TAB, KC_Q, KC_W, KC_E, KC_R,
        KC_CAPS, KC_A, KC_S, KC_D, KC_F,
        KC_LSFT, KC_Z, KC_X, KC_C, KC_V,
        KC_LALT, KC_UP, KC_DOWN, KC_RIGHT, KC_LEFT,
